  function pdfLines(items){var lines=[];items.forEach(function(it){var t=String(it.str||'').trim();if(!t)return;var y=Math.round((it.transform&&it.transform[5]||0)*2)/2,x=it.transform&&it.transform[4]||0;var line=lines.find(function(l){return Math.abs(l.y-y)<=2;});if(!line){line={y:y,parts:[]};lines.push(line);}line.parts.push({x:x,text:t});});lines.sort(function(a,b){return b.y-a.y;});return lines.map(function(l){l.parts.sort(function(a,b){return a.x-b.x;});return l.parts.map(function(p){return p.text;}).join(' ');}).join('\n');}
