  function render(){if(view.querySelector('#cutResult'))return;view.innerHTML='<div class="cutPage"><header class="cutHeader"><div><button type="button" id="cutBack" class="cutSecondary" hidden>← Voltar às OPs</button><small>OPERAÇÃO / CORTE</small><h1 id="cutTitle">OPs de corte</h1><p id="cutSubtitle">Consulte as OPs publicadas pelo PCP, materiais, códigos, cálculos e arquivo original.</p></div><button type="button" id="cutNewOp" class="cutPrimary">Nova OP</button></header><section id="cutSavedOps" class="cutSavedOps" hidden><div class="cutSavedHead"><div><b>OPs de corte</b><span id="cutSavedCount"></span></div><input id="cutOpSearch" type="search" placeholder="Buscar AP, lote, cliente ou número da OP" aria-label="Buscar OP salva"></div><div class="cutKpis"><div><small>OPS SALVAS</small><strong id="cutKpiOps">0</strong></div><div><small>PEÇAS NO PAINEL</small><strong id="cutKpiPieces">0</strong></div><div><small>OPS SEM CÓDIGO</small><strong id="cutKpiPending">0</strong></div><div><small>ÚLTIMA ATUALIZAÇÃO</small><strong id="cutKpiLatest">—</strong></div></div><div id="cutSavedList" class="cutSavedList"></div></section><div class="cutUpload" id="cutUploadPanel" hidden><div><b>Enviar OP</b><p>PDF ou Excel (.xlsx/.xls). O PCP importa a ficha; o sistema cria OP, requisição em Pendentes para o corte escolher materiais, máquinas e prioridades, e romaneio.</p><span id="cutOriginalName" class="cutOriginalName"></span></div><div class="cutUploadActions"><button type="button" id="cutOpenOriginal" class="cutSecondary" hidden>Ver OP original</button><label class="cutUploadButton">Escolher arquivo<input id="cutFile" type="file" accept=".pdf,.xlsx,.xls,application/pdf,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" hidden></label></div></div><section id="cutSeparationTop" class="cutSeparationTop" hidden></section><section class="cutInlineOp" id="cutInlineOp" hidden><div class="cutInlineHead"><div><small>OP ORIGINAL COMPLETA</small><h2 id="cutInlineTitle"></h2><p>Todas as páginas, desenhos e observações do arquivo original.</p></div><div class="cutOriginalActions"><button type="button" id="cutInlineBack" class="cutSecondary">← Voltar às OPs</button><a id="cutInlineDownload" class="cutSecondary">Baixar original</a><button type="button" id="cutInlineToggle" class="cutSecondary">Recolher OP</button></div></div><div id="cutInlineBody"><div id="cutInlinePdfPages" class="cutPdfPages"></div><div id="cutInlineExcelNotice" class="cutExcelNotice" hidden><strong>Desenhos e objetos do Excel</strong><p>Para conferir a OP completa, baixe o original e abra no Excel. A composição e as fórmulas extraídas aparecem abaixo.</p></div></div></section><div class="cutAlert" id="cutAlert" hidden></div><div id="cutResult"><div class="cutEmpty"><span>01</span><b>Selecione uma OP para consultar</b><p>Abra uma ficha salva acima ou clique em Nova OP para cadastrar um arquivo.</p></div></div></div><dialog id="cutOriginalDialog" class="cutOriginalDialog" aria-labelledby="cutOriginalTitle"><div class="cutOriginalHead"><div><small>ARQUIVO ORIGINAL</small><h2 id="cutOriginalTitle"></h2></div><div class="cutOriginalActions"><a id="cutOriginalDownload" class="cutSecondary">Baixar original</a><button type="button" id="cutCloseOriginal" class="cutSecondary">Fechar</button></div></div><div id="cutPdfPages" class="cutPdfPages"></div><div id="cutExcelNotice" class="cutExcelNotice" hidden><strong>Desenhos e objetos do Excel</strong><p>Para ver a ficha completa com os desenhos e a formatação original, baixe o arquivo acima e abra no Excel.</p></div></dialog><dialog id="cutDispatchDialog" class="cutDispatchDialog" aria-labelledby="cutDispatchTitle"><div class="cutDispatchHead"><div><small>OP DE CORTE / REQUISIÇÃO</small><h2 id="cutDispatchTitle">Montar requisição</h2></div><button type="button" id="cutDispatchCancel" class="cutSecondary">Fechar</button></div><div id="cutDispatchBody"></div><div class="cutDispatchFooter"><p id="cutDispatchError" role="alert"></p><button type="button" id="cutDispatchSend" class="cutPrimary">Enviar para separação</button></div></dialog>';view.insertAdjacentHTML('beforeend', '<dialog id="cutReleaseDialog" class="cutDispatchDialog" aria-labelledby="cutReleaseTitle"><div class="cutDispatchHead"><div><small>CORTE / OP PUBLICADA PELO PCP</small><h2 id="cutReleaseTitle">Máquinas e prioridades</h2></div><button type="button" id="cutReleaseCancel" class="cutSecondary">Fechar</button></div><div id="cutReleaseBody"></div><div class="cutDispatchFooter"><p id="cutReleaseError" role="alert"></p><button type="button" id="cutReleaseSend" class="cutPrimary">Enviar materiais selecionados</button></div></dialog>');view.querySelector('#cutBack').addEventListener('click',showListMode);view.querySelector('#cutInlineBack').addEventListener('click',showListMode);view.querySelector('#cutNewOp').addEventListener('click',openCreateMode);view.querySelector('#cutFile').addEventListener('change',function(ev){var selected=ev.target.files[0];ev.target.value='';handleFile(selected);});view.querySelector('#cutInlineToggle').addEventListener('click',function(){var body=view.querySelector('#cutInlineBody');body.hidden=!body.hidden;this.textContent=body.hidden?'Mostrar OP completa':'Recolher OP';});view.querySelector('#cutOpSearch').addEventListener('input',paintSavedOps);view.querySelector('#cutSavedList').addEventListener('click',function(ev){var b=ev.target.closest('[data-op-id]');if(b)openSavedOp(b.dataset.opId);});renderSavedOps();view.querySelector('#cutOpenOriginal').addEventListener('click',showOriginal);view.querySelector('#cutCloseOriginal').addEventListener('click',closeOriginal);view.querySelector('#cutOriginalDialog').addEventListener('click',function(ev){if(ev.target===this)closeOriginal();});view.querySelector('#cutOriginalDialog').addEventListener('close',function(){previewGeneration++;});view.querySelector('#cutDispatchCancel').addEventListener('click',function(){view.querySelector('#cutDispatchDialog').close();});view.querySelector('#cutDispatchSend').addEventListener('click',sendDispatchDraft);view.querySelector('#cutReleaseCancel').addEventListener('click',function(){view.querySelector('#cutReleaseDialog').close();});view.querySelector('#cutReleaseSend').addEventListener('click',releaseToLogistics);}
