      var separation=separationFor(op),ids=new Set(separation.requests.map(function(request){return String(request.id||'');}).filter(Boolean));
      var linked=requests.filter(function(request){return request&&(String(request.source_cut_op_id||'')===String(op.id)||ids.has(String(request.id||'')));});
