      return {op:op,separation:{linked:separation.linked,percent:separation.percent,bippedPercent:separation.bippedPercent,requests:linked},expedition:{record:record,percent:output.confirmedPercent,quantities:output},overallPercent:overall.percent,urgent:urgentFor(op),shipment:window.CutExpeditionCore.shipment(shippingDates(op.lot),record)};
